SELECT TO_CHAR(MBC.DTLANC, 'DD/MM/YYYY') AS DIA, SUM((NVL(MBC.VLRLANC,0) * NVL(MBC.RECDESP,0))) AS OUTRAS_MOVIMENTACOES FROM TGFMBC MBC LEFT JOIN TGFFIN FIN ON FIN.NUBCO = MBC.NUBCO LEFT JOIN TSICTA CTA ON CTA.CODCTABCOINT = MBC.CODCTABCOINT LEFT JOIN TSIEMP EMP ON EMP.CODEMP = CTA.CODEMP WHERE FIN.NUFIN IS NULL AND TRUNC(MBC.DTLANC) >= TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) AND TRUNC(MBC.DTLANC) <= TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_FIM_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) + 15)) AND (:VAR_EMPRESA_FC IS NULL OR :VAR_EMPRESA_FC = '' OR INSTR(',' || :VAR_EMPRESA_FC || ',', ',' || EMP.CODEMP || ',') > 0) AND (:VAR_CONTA_BANCARIA_FC IS NULL OR :VAR_CONTA_BANCARIA_FC = '' OR INSTR(',' || :VAR_CONTA_BANCARIA_FC || ',', ',' || TO_CHAR(CTA.CODCTABCOINT) || ',') > 0) GROUP BY TO_CHAR(MBC.DTLANC, 'DD/MM/YYYY')